const PI = Math.PI;
const boxColor = 0x222222;
const helixColor = 0x2ba3d8;

// ── Bounding box (12 edges) ────────────────────────────────────────────────
const boxEdges = [];
const corners = [
  [-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0],
  [-1,-1,PI],[1,-1,PI],[1,1,PI],[-1,1,PI]
];
// Bottom face edges: 0-1, 1-2, 2-3, 3-0
// Top face edges: 4-5, 5-6, 6-7, 7-4
// Vertical edges: 0-4, 1-5, 2-6, 3-7
