  const t = (i / N) * PI;
  helixPts.push(new THREE.Vector3(Math.cos(t), Math.sin(t), t));
}
const helixCurve = new THREE.CatmullRomCurve3(helixPts);
const tubeGeo = new THREE.TubeGeometry(helixCurve, 200, 0.025, 8, false);
const tubeMat = new THREE.MeshBasicMaterial({ color: helixColor });
