const PI = Math.PI;
const boxColor = 0x222222;
const helixColor = 0x2ba3d8;

// Helper: figure coords → world coords
function f2w(fx, fy, fz) {
  return new THREE.Vector3(-fx, fz, -fy);
}

// ── Bounding box (12 edges) ────────────────────────────────────────────────
// Figure corners: x∈[-1,1], y∈[-1,1], z∈[0,π]
const figCorners = [
  [-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0],
  [-1,-1,PI],[1,-1,PI],[1,1,PI],[-1,1,PI]
];
const worldCorners = figCorners.map(c => f2w(c[0], c[1], c[2]));
const edgePairs = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
const edgeMat = new THREE.LineBasicMaterial({ color: boxColor });
for (const [a, b] of edgePairs) {
  const geo = new THREE.BufferGeometry().setFromPoints([worldCorners[a], worldCorners[b]]);
  scene.add(new THREE.Line(geo, edgeMat));
}

// ── Helix curve: fig (cos t, sin t, t) → world (-cos t, t, -sin t) ───────
const helixPts = [];
const N = 200;
for (let i = 0; i <= N; i++) {
  const t = (i / N) * PI;
  helixPts.push(f2w(Math.cos(t), Math.sin(t), t));
}
const helixCurve = new THREE.CatmullRomCurve3(helixPts);
const tubeGeo = new THREE.TubeGeometry(helixCurve, 200, 0.03, 8, false);
const tubeMat = new THREE.MeshBasicMaterial({ color: helixColor });
