function f2w(fx, fy, fz) {
  return new THREE.Vector3(-fx, fz, -fy);
}

// ── Bounding box (12 edges) ────────────────────────────────────────────────
// Figure corners: x∈[-1,1], y∈[-1,1], z∈[0,π]
