scene.add(startDot);

const endDot = new THREE.Mesh(dotGeo.clone(), dotMat.clone());
endDot.position.copy(f2w(-1, 0, PI));
scene.add(endDot);

// ── Arrowhead at t ≈ 2.2 ──────────────────────────────────────────────────
const tArrow = 2.2;
const arrowWorldPos = f2w(Math.cos(tArrow), Math.sin(tArrow), tArrow);
// Tangent in figure: (-sin t, cos t, 1); mapped to world: (sin t, 1, -cos t)
const tangentWorld = new THREE.Vector3(Math.sin(tArrow), 1, -Math.cos(tArrow)).normalize();
const coneGeo = new THREE.ConeGeometry(0.07, 0.2, 12);
const coneMat = new THREE.MeshBasicMaterial({ color: helixColor });
const arrowhead = new THREE.Mesh(coneGeo, coneMat);
arrowhead.position.copy(arrowWorldPos);
const upVec = new THREE.Vector3(0, 1, 0);
const quat = new THREE.Quaternion().setFromUnitVectors(upVec, tangentWorld);
arrowhead.quaternion.copy(quat);
scene.add(arrowhead);

// ── Tracer dot ─────────────────────────────────────────────────────────────
const tracerGeo = new THREE.SphereGeometry(0.06, 16, 16);
const tracerMat = new THREE.MeshBasicMaterial({ color: 0xe04040 });
const tracer = new THREE.Mesh(tracerGeo, tracerMat);
tracer.position.copy(f2w(1, 0, 0));
scene.add(tracer);

// ── Camera (call BEFORE labels so auto-fit measures geometry only) ────────
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 45,
  elevationDeg: 35.26,
  heightFraction: 0.72
});

// ── Labels ─────────────────────────────────────────────────────────────────
// Axis labels
addLabel('<i>x</i>', f2w(0.3, -1.5, -0.3), { fontSize: '15px', bold: true });
addLabel('<i>y</i>', f2w(-0.2, 1.5, PI + 0.3), { fontSize: '15px', bold: true });
addLabel('<i>z</i>', f2w(-1.5, -1.3, PI * 0.45), { fontSize: '15px', bold: true });

// x-axis ticks (along front-bottom edge, y=-1, z=0 in figure)
addLabel('1', f2w(1, -1.25, -0.25), { fontSize: '12px' });
addLabel('0', f2w(0, -1.25, -0.25), { fontSize: '12px' });
addLabel('−1', f2w(-1, -1.25, -0.25), { fontSize: '12px' });

// y-axis ticks (along right-bottom edge, x=1, z=0 in figure)
addLabel('1', f2w(1.25, 1, -0.25), { fontSize: '12px' });
addLabel('−1', f2w(1.25, -1, -0.25), { fontSize: '12px' });

// z-axis ticks (along left-front vertical edge, x=-1, y=-1 in figure)
addLabel('0', f2w(-1.25, -1.25, -0.1), { fontSize: '12px' });
addLabel('π', f2w(-1.25, -1.25, PI + 0.1), { fontSize: '12px' });

// Point labels — separated to avoid overlap
addLabel('(1, 0, 0)', f2w(1, 0, 0), { offset: [0, 28], fontSize: '13px', bold: true });
addLabel('(−1, 0, π)', f2w(-1, 0, PI), { offset: [-10, -22], fontSize: '13px', bold: true });
addLabel('0', f2w(-1, 0, PI), { offset: [30, -8], fontSize: '13px' });

// ── Slider interaction ─────────────────────────────────────────────────────
const slider = document.getElementById('traceT');
const readoutPos = document.getElementById('readoutPos');
const readoutArc = document.getElementById('readoutArc');
const readoutDs = document.getElementById('readoutDs');

function updateTracer(t) {
  const x = Math.cos(t);
  const y = Math.sin(t);
  const z = t;
  tracer.position.copy(f2w(x, y, z));
  const s = Math.SQRT2 * t;
  readoutPos.textContent = `(x, y, z) = (${x.toFixed(2)}, ${y.toFixed(2)}, ${z.toFixed(2)})`;
  readoutArc.textContent = `s = √2·t = ${s.toFixed(3)}`;
  readoutDs.textContent = `ds = √2 dt ≈ ${(Math.SQRT2).toFixed(4)} dt`;
}

slider.addEventListener('input', () => {
  updateTracer(parseFloat(slider.value));
});

// ── Demo steps ─────────────────────────────────────────────────────────────
function goToStep(stepIndex) {
  const steps = [0, PI / 2, PI];
  const target = steps[stepIndex];
  if (target === undefined) return;
  const current = parseFloat(slider.value);
  const duration = 600;
  const startTime = performance.now();
  function animateStep(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const val = current + (target - current) * eased;
    slider.value = val;
    updateTracer(val);
    if (progress < 1) requestAnimationFrame(animateStep);
  }
  requestAnimationFrame(animateStep);
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));

// ── Interactive elements ───────────────────────────────────────────────────
registerInteractive(helixMesh, {
  title: 'Helix C',
  body: 'The curve C is parameterized by r(t) = (cos t, sin t, t) for t ∈ [0, π]. Its speed is |r′(t)| = √(sin²t + cos²t + 1) = √2, so ds = √2 dt.',
  tooltip: 'Helix: x=cos t, y=sin t, z=t'
});

registerInteractive(startDot, {
  title: 'Start point (1, 0, 0)',
  body: 'At t = 0: x = cos 0 = 1, y = sin 0 = 0, z = 0. Arc length s = 0.',
  tooltip: 'Start: (1, 0, 0) at t=0'
});

registerInteractive(endDot, {
  title: 'End point (−1, 0, π)',
  body: 'At t = π: x = cos π = −1, y = sin π = 0, z = π. Total arc length s = √2·π.',
  tooltip: 'End: (−1, 0, π) at t=π'
});

// Initial readout
updateTracer(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
