Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Parameter t
  <input type="range" id="traceT" min="0" max="3.14159" step="0.01" value="0">
</label>
<div id="readout" style="font-size:11px;line-height:1.5;padding:4px 6px;background:#f0f8ff;border-radius:4px;border:1px solid #ccc;">
  <div id="readoutPos">(x, y, z) = (1.00, 0.00, 0.00)</div>
  <div id="readoutArc">s = √2·t = 0.000</div>
  <div id="readoutDs">ds = √2 dt</div>
</div>
<button id="btnStep0">Step 1: Start</button>
<button id="btnStep1">Step 2: Halfway</button>
<button id="btnStep2">Step 3: End</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──────────────────────────────────────────────────────────
// Coordinate mapping: figure (fx, fy, fz) → world (fx, fz, fy)
// figure-x → world X (right), figure-z → world Y (up), figure-y → world Z (depth)
//
// box edges    → 12 LineSegments, color #222222
// helix curve  → TubeGeometry(200 segments, radius 0.035), color #2ba3d8
// start dot    → SphereGeometry(0.07), color #2ba3d8
// end dot      → SphereGeometry(0.07), color #2ba3d8
// arrowhead    → ConeGeometry(0.06, 0.18), color #2ba3d8, at t≈2.2
// tracer dot   → SphereGeometry(0.06), color #e04040, hidden at t=0
// axis labels  → addLabel for x, y, z, tick values, point coords

const PI = Math.PI;
const boxColor = 0x222222;
const helixColor = 0x2ba3d8;

// Helper: figure coords → world coords
function f2w(fx, fy, fz) {
  return new THREE.Vector3(fx, fz, fy);
}

// ── Bounding box (12 edges) ────────────────────────────────────────────────
// Figure corners: x∈[-1,1], y∈[-1,1], z∈[0,π]
const figCorners = [
  [-1,-1,0],[1,-1,0],[1,1,0],[-1,1,0],
  [-1,-1,PI],[1,-1,PI],[1,1,PI],[-1,1,PI]
];
const worldCorners = figCorners.map(c => f2w(c[0], c[1], c[2]));
const edgePairs = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
const edgeMat = new THREE.LineBasicMaterial({ color: boxColor });
for (const [a, b] of edgePairs) {
  const geo = new THREE.BufferGeometry().setFromPoints([worldCorners[a], worldCorners[b]]);
  scene.add(new THREE.Line(geo, edgeMat));
}

// ── Helix curve: fig (cos t, sin t, t) → world (cos t, t, sin t) ─────────
const helixPts = [];
const N = 200;
for (let i = 0; i <= N; i++) {
  const t = (i / N) * PI;
  helixPts.push(f2w(Math.cos(t), Math.sin(t), t));
}
const helixCurve = new THREE.CatmullRomCurve3(helixPts);
const tubeGeo = new THREE.TubeGeometry(helixCurve, 200, 0.035, 8, false);
const tubeMat = new THREE.MeshBasicMaterial({ color: helixColor });
const helixMesh = new THREE.Mesh(tubeGeo, tubeMat);
scene.add(helixMesh);

// ── Start and end dots ─────────────────────────────────────────────────────
const dotGeo = new THREE.SphereGeometry(0.07, 16, 16);
const dotMat = new THREE.MeshBasicMaterial({ color: helixColor });
const startDot = new THREE.Mesh(dotGeo, dotMat);
startDot.position.copy(f2w(1, 0, 0));
scene.add(startDot);

const endDot = new THREE.Mesh(dotGeo.clone(), dotMat.clone());
endDot.position.copy(f2w(-1, 0, PI));
scene.add(endDot);

// ── Arrowhead at t ≈ 2.2 ──────────────────────────────────────────────────
const tArrow = 2.2;
const arrowWorldPos = f2w(Math.cos(tArrow), Math.sin(tArrow), tArrow);
// Tangent in figure: (-sin t, cos t, 1); mapped to world: (-sin t, 1, cos t)
const tangentWorld = new THREE.Vector3(-Math.sin(tArrow), 1, Math.cos(tArrow)).normalize();
const coneGeo = new THREE.ConeGeometry(0.06, 0.18, 12);
const coneMat = new THREE.MeshBasicMaterial({ color: helixColor });
const arrowhead = new THREE.Mesh(coneGeo, coneMat);
arrowhead.position.copy(arrowWorldPos);
const upVec = new THREE.Vector3(0, 1, 0);
const quat = new THREE.Quaternion().setFromUnitVectors(upVec, tangentWorld);
arrowhead.quaternion.copy(quat);
scene.add(arrowhead);

// ── Tracer dot (hidden at t=0) ────────────────────────────────────────────
const tracerGeo = new THREE.SphereGeometry(0.06, 16, 16);
const tracerMat = new THREE.MeshBasicMaterial({ color: 0xe04040 });
const tracer = new THREE.Mesh(tracerGeo, tracerMat);
tracer.position.copy(f2w(1, 0, 0));
tracer.visible = false;
scene.add(tracer);

// ── Camera ─────────────────────────────────────────────────────────────────
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 12, z: 24 },
  heightFraction: 0.7
});

// ── Labels ─────────────────────────────────────────────────────────────────
// Axis name labels
addLabel('<i>x</i>', f2w(0.4, -1.3, -0.35), { fontSize: '15px', bold: true });
addLabel('<i>y</i>', f2w(1.3, 1.3, 0.1), { fontSize: '15px', bold: true });
addLabel('<i>z</i>', f2w(-1.45, -1.3, PI * 0.5), { fontSize: '15px', bold: true });

// x-axis ticks along front-bottom edge (y=-1, z=0 in figure)
addLabel('1', f2w(1, -1.15, -0.3), { fontSize: '12px' });
addLabel('0', f2w(0, -1.15, -0.3), { fontSize: '12px' });
addLabel('−1', f2w(-1, -1.15, -0.3), { fontSize: '12px' });

// y-axis ticks along right-bottom edge (x=1, z=0 in figure)
addLabel('1', f2w(1.2, 1, -0.25), { fontSize: '12px' });
addLabel('−1', f2w(1.2, -1, -0.25), { fontSize: '12px' });

// z-axis ticks along left-front vertical edge (x=-1, y=-1 in figure)
addLabel('0', f2w(-1.25, -1.2, -0.15), { fontSize: '12px' });
addLabel('π', f2w(-1.25, -1.2, PI + 0.15), { fontSize: '12px' });

// Point labels
addLabel('(1, 0, 0)', f2w(1, 0, 0), { offset: [-15, 30], fontSize: '13px', bold: true });
addLabel('(−1, 0, π)', f2w(-1, 0, PI), { offset: [-10, -25], fontSize: '13px', bold: true });
addLabel('0', f2w(-1, 0, PI), { offset: [30, -10], fontSize: '13px' });

// ── Slider interaction ─────────────────────────────────────────────────────
const slider = document.getElementById('traceT');
const readoutPos = document.getElementById('readoutPos');
const readoutArc = document.getElementById('readoutArc');
const readoutDs = document.getElementById('readoutDs');

function updateTracer(t) {
  const x = Math.cos(t);
  const y = Math.sin(t);
  const z = t;
  tracer.position.copy(f2w(x, y, z));
  tracer.visible = t > 0.02;
  const s = Math.SQRT2 * t;
  readoutPos.textContent = `(x, y, z) = (${x.toFixed(2)}, ${y.toFixed(2)}, ${z.toFixed(2)})`;
  readoutArc.textContent = `s = √2·t = ${s.toFixed(3)}`;
  readoutDs.textContent = `ds = √2 dt ≈ ${(Math.SQRT2).toFixed(4)} dt`;
}

slider.addEventListener('input', () => {
  updateTracer(parseFloat(slider.value));
});

// ── Demo steps ─────────────────────────────────────────────────────────────
function goToStep(stepIndex) {
  const steps = [0, PI / 2, PI];
  const target = steps[stepIndex];
  if (target === undefined) return;
  const current = parseFloat(slider.value);
  const duration = 600;
  const startTime = performance.now();
  function animateStep(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    const val = current + (target - current) * eased;
    slider.value = val;
    updateTracer(val);
    if (progress < 1) requestAnimationFrame(animateStep);
  }
  requestAnimationFrame(animateStep);
}

document.getElementById('btnStep0').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));

// ── Interactive elements ───────────────────────────────────────────────────
registerInteractive(helixMesh, {
  title: 'Helix C',
  body: 'The curve C is parameterized by r(t) = (cos t, sin t, t) for t ∈ [0, π]. Its speed is |r′(t)| = √(sin²t + cos²t + 1) = √2, so ds = √2 dt.',
  tooltip: 'Helix: x=cos t, y=sin t, z=t'
});

registerInteractive(startDot, {
  title: 'Start point (1, 0, 0)',
  body: 'At t = 0: x = cos 0 = 1, y = sin 0 = 0, z = 0. Arc length s = 0.',
  tooltip: 'Start: (1, 0, 0) at t=0'
});

registerInteractive(endDot, {
  title: 'End point (−1, 0, π)',
  body: 'At t = π: x = cos π = −1, y = sin π = 0, z = π. Total arc length s = √2·π.',
  tooltip: 'End: (−1, 0, π) at t=π'
});

// Initial readout
updateTracer(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

